     1	import React from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	import { useUiCopy } from 'app/hooks/useUiCopy';
     4	
     5	// English fallback for useUiCopy() below — not a prop. Named so the string appears once, the
     6	// same way zimmSubscribeSection/index.tsx keeps its fallbacks.
     7	const LABEL_FALLBACK = 'Style Code:';
     8	
     9	type ZimmProductStyleCodeProps = {
    10	  /**
    11	   * The master product's style number. This is the style code shown to shoppers, which is not
    12	   * the same value as the variant `product.id`.
    13	   */
    14	  value?: string;
    15	};
    16	
    17	/**
    18	 * Atom — the "Style Code: 7300JS261" line. Renders nothing when no style code is available.
    19	 *
    20	 * The label is microcopy, so it comes from `useUiCopy()` rather than a prop: it is the same
    21	 * string for every caller, and the hook is Context-backed app-wide static content, which
    22	 * components.md explicitly allows a presentational leaf to read. With no UiCopyProvider
    23	 * mounted (Storybook, a unit test) it degrades to the fallback above, so this stays renderable
    24	 * with zero setup.
    25	 */
    26	export const ZimmProductStyleCode = ({ value }: ZimmProductStyleCodeProps) => {
    27	  const styles = useMultiStyleConfig('ZimmProductStyleCode', {});
    28	  const { t } = useUiCopy();
    29	  if (!value) return null;
    30	
    31	  return (
    32	    <chakra.div __css={styles.root} textStyle="caption" data-testid="product-style-code">
    33	      <chakra.span __css={styles.label}>{t('pdp.styleCodeLabel', LABEL_FALLBACK)}</chakra.span>
    34	      {/*
    35	        A real space so `textContent` — what a screen reader reads out and what a shopper
    36	        copies — is "Style Code: 8637DS241", matching both composed page designs. It adds no
    37	        visual width: a whitespace-only anonymous flex item is not rendered (CSS Flexbox §4),
    38	        so the 4px `gap` in the recipe remains the only spacing.
    39	      */}{' '}
    40	      <chakra.span __css={styles.value}>{value}</chakra.span>
    41	    </chakra.div>
    42	  );
    43	};

