 1	/**
 2	 * Guard: a multipart recipe's declared `parts` must cover every part the component actually
 3	 * reads off `useMultiStyleConfig`.
 4	 *
 5	 * The failure this catches is silent. Chakra returns a styles object keyed by the recipe's
 6	 * `parts`; reading a key that is not declared yields `undefined`, and `__css={undefined}` is a
 7	 * perfectly legal prop. The element renders unstyled and nothing — not `tsc`, not eslint, not
 8	 * an axe run, not a `play` that only asserts text — reports it.
 9	 *
10	 * Comparing `parts` against the recipe's own `baseStyle` keys would not catch it: renaming a
11	 * part in both places at once keeps them consistent with each other and still breaks the
12	 * component. The component's reads are the only source of truth for what it needs, so this
13	 * walks the component source.
14	 *
15	 * Scope: `overrides/app/components/ui-kits/**`. Recipes elsewhere are covered by
16	 * `theme/components/recipeGuards.test.ts`.
17	 */
18	import { describe, expect, test } from 'vitest';
19	import { existsSync, readFileSync, readdirSync } from 'node:fs';
20	import path from 'node:path';
21	
22	const UI_KITS = path.resolve(process.cwd(), 'overrides/app/components/ui-kits');
23	
24	const walk = (dir: string): string[] =>
25	  readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
26	    const full = path.join(dir, entry.name);
27	    return entry.isDirectory() ? walk(full) : [full];
28	  });
29	
30	/** `parts: ['root', 'label']` — the literal array in a `.css.ts` recipe. */
31	const PARTS_RE = /\bparts:\s*\[([^\]]*)\]/;
32	/** `styles.label` and `styles['label']`, the two ways a component reads a resolved part. */
33	const READ_RE = /\bstyles(?:\.([A-Za-z][A-Za-z0-9]*)|\[\s*'([^']+)'\s*\])/g;
34	
35	type MultipartRecipe = {
36	  name: string;
37	  recipeFile: string;
38	  componentFile: string;
39	  declared: string[];
40	  read: string[];
41	  /**
42	   * Whether the sibling component was found. Recorded rather than thrown on: reading a missing
43	   * file here would fail *collection*, and vitest reports that as one error for the whole file
44	   * — taking the vacuity guard below down with it. A guard that disappears when its own
45	   * assumption breaks is the exact failure this suite exists to prevent.
46	   */
47	  componentFound: boolean;
48	};
49	
50	const collectMultipartRecipes = (): MultipartRecipe[] =>
51	  walk(UI_KITS)
52	    .filter((file) => file.endsWith('.css.ts'))
53	    .flatMap((recipeFile) => {
54	      const declaredMatch = PARTS_RE.exec(readFileSync(recipeFile, 'utf8'));
55	      if (!declaredMatch) return []; // single-part recipe — nothing to reconcile
56	
57	      const declared = declaredMatch[1]
58	        .split(',')
59	        .map((entry) => entry.trim().replace(/^['"]|['"]$/g, ''))
60	        .filter(Boolean);
61	
62	      const componentFile = path.join(path.dirname(recipeFile), 'index.tsx');
63	      const componentFound = existsSync(componentFile);
64	      const read = componentFound
65	        ? [...readFileSync(componentFile, 'utf8').matchAll(READ_RE)].map((match) => match[1] ?? match[2])
66	        : [];
67	
68	      return [
69	        { name: path.basename(recipeFile, '.css.ts'), recipeFile, componentFile, declared, read, componentFound },
70	      ];
71	    });
72	
73	const recipes = collectMultipartRecipes();
74	
75	describe('multipart recipes declare every part their component reads', () => {
76	  test.each(recipes.map((recipe) => [recipe.name, recipe] as const))('%s', (_name, recipe) => {
77	    expect(recipe.componentFound, `no component found at ${recipe.componentFile} for ${recipe.recipeFile}`).toBe(true);
78	    const undeclared = [...new Set(recipe.read)].filter((part) => !recipe.declared.includes(part));
79	    expect(undeclared, `${recipe.componentFile} reads parts absent from ${recipe.recipeFile}`).toEqual([]);
80	  });
81	
82	  // Vacuity guard. A suite built by walking the filesystem passes trivially when the walk
83	  // returns nothing — a moved directory or a renamed suffix would turn this file into a
84	  // no-op that still reports green. Mirrors recipeGuards.test.ts's own self-test.
85	  test('the walk actually collected something', () => {
86	    expect(walk(UI_KITS).length).toBeGreaterThan(0);
87	    expect(recipes.length).toBeGreaterThan(0);
88	    expect(recipes.every((recipe) => recipe.declared.length > 0)).toBe(true);
89	    expect(recipes.some((recipe) => recipe.read.length > 0)).toBe(true);
90	  });
91	});

